import sys

def max_ones(n, m):
    if m == 1:
        return n * n
    if n < m:
        return 0
    return (n // m) * (n // m) * (m * m - 1) + (n // m) * (n % m) * (m - 1) + (n % m) * (n // m) * (m - 1) + (n % m) ** 2

def find_nm(x):
    if x == 0:
        return (1, 1)
    for m in range(1, 1000):
        for n in range(m, 1000000):
            if max_ones(n, m) == x:
                return (n, m)
    return (-1,)

t = int(input().strip())
for _ in range(t):
    x = int(input().strip())
    nm = find_nm(x)
    if len(nm) == 1:
        print(-1)
    else:
        print(nm[0], nm[1])
